/* T计划 · all state stays in this browser. No network or runtime dependencies. */
(() => {
'use strict';
const G = window.TG, C = window.TGCourses, K = window.TGCalendar, QA = window.TGQuickAdd, KEY = 'tgrowth.v1';
const app = document.querySelector('#app'), dialog = document.querySelector('#dialog');
const initialWeek = () => G.addDays('2026-09-07',(Math.max(1,Math.min(20,G.teachingWeek(G.today())))-1)*7);
let state, lastRaw, blocked = false, page = 'today', selected = initialWeek(), pendingImport = null;
let courseHistoryFilter = '', taskStatusFilter = 'all', focusRange = '7d';
// Quick-add draft survives re-renders; quickHandoff marks text passed on to the full task form.
const emptyQuick = () => ({text:'',category:'',minutes:''});
let quick = emptyQuick(), quickHandoff = null, quickComposing = false;
const clone = value => JSON.parse(JSON.stringify(value));
const esc = v => String(v ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const fmt = minutes => (Math.round(minutes / 60 * 100) / 100).toLocaleString('zh-CN',{maximumFractionDigits:2});
const removedCategories = new Set(['agent','power','fitness','other']);
const categories = G.CATEGORIES.filter(c=>!removedCategories.has(c.id));
const cat = id => categories.find(c => c.id === id)?.label || '历史分类';
const weekdays = ['一','二','三','四','五','六','日'];
const statusLabel = {todo:'未开始',doing:'进行中',done:'已完成'};
const priorityLabel = {high:'高',medium:'中',low:'低'};
const btn = (label, action, id = '', cls = '') => `<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const input = (label,name,value='',type='text',extra='') => `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const textarea = (label,name,value='',extra='') => `<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" maxlength="4000" ${extra}>${esc(value)}</textarea></div>`;
const select = (label,name,options,value) => `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
const catSelect = v => select('分类','category',[...categories.filter(c=>c.id!=='stocks'||!state.settings.hideStocks||v==='stocks').map(c=>[c.id,c.label]),...(removedCategories.has(v)?[[v,'历史分类（保留原记录）']]:[])],v);
const todayDay = () => (new Date(G.today()+'T12:00:00').getDay()+6)%7+1;
const learningLevels = {unreviewed:'尚未复盘',minimum:'达到保底线',standard:'达到达标线',stretch:'达到进阶线',blocked:'存在卡点'};
const learningEvidence = {explain:'我能不看教材解释核心概念',draw:'我能独立画出关键图 / 结构',solve:'我能独立完成基础题',teach:'我能把内容讲给别人',stuck:'我仍然存在卡点'};
function uiIcon(name){const paths={target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',book:'<path d="M3 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H3Zm18 0h-6a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h5Z"/>',person:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-3a7 7 0 0 1 14 0v3"/>',calendar:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 10h16"/>',arrow:'<path d="m9 5 7 7-7 7"/>'};return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.book}</svg>`;}
function courseSession(key){
 const [date,courseId]=key.split('|'),week=G.teachingWeek(date),course=C.forWeek(week).find(c=>c.id===courseId)||C.courses.find(c=>c.id===courseId);
 if(!course||!course.weeks.includes(week)||G.addDays(G.weekStart(date),course.day-1)!==date)throw new Error('找不到这一次课程，请从对应日期的课表打开。');
 const saved=G.getCoursePlan(state,courseId,date);
 return {course,date,week,saved,plan:saved||{courseId,week,date,topic:'',preQuestions:[],minimumGoals:[],standardGoals:[],stretchGoals:[],evidence:[],reflection:'',unresolvedProblem:'',levelReached:'unreviewed'}};
}
function hasLearningGoals(p){return p&&(p.topic.trim()||p.preQuestions.length||p.minimumGoals.length||p.standardGoals.length||p.stretchGoals.length);}
function learningBadge(courseId,date){const p=G.getCoursePlan(state,courseId,date),blocked=p&&(p.levelReached==='blocked'||p.evidence.includes('stuck')||p.unresolvedProblem.trim());const label=blocked?'存在卡点':p&&p.levelReached!=='unreviewed'?{minimum:'保底完成',standard:'达标完成',stretch:'进阶完成'}[p.levelReached]:hasLearningGoals(p)?'尚未复盘':p&&(p.reflection.trim()||p.evidence.length)?'已记成果':'尚未规划';return `<span class="learning-badge ${blocked?'has-question':''}" data-learning-status="${p?.levelReached||'unplanned'}">${label}</span>`;}
function learningTaskLink(t){const p=t.coursePlanId&&state.courseLearningPlans.find(p=>p.id===t.coursePlanId);return p?`<p class="meta course-task-link">${btn('关联课程：'+esc(C.courses.find(c=>c.id===p.courseId).name)+' · '+p.date,'course-history-open',p.id,'quiet small')}</p>`:'';}
function learningList(items){return items.length?`<ul class="learning-list">${items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p class="muted">尚未填写</p>';}
function courseTitle(c){return c.displayName||c.name;}
function scheduleBadge(c){return c.attendanceStatus==='occupied'?`<span class="badge warm" title="${esc(c.attendanceNotice)}">${esc(c.statusLabel)} · 上实验课</span>`:'';}
function courseDetail(key,activeTab='plan'){
 const {course:c,date,week,plan:p,saved}=courseSession(key),task=saved&&state.tasks.find(t=>t.coursePlanId===saved.id);
 modal('课程详情',`<div data-course-session="${esc(key)}"><header class="course-detail-hero"><h3>${esc(courseTitle(c))}</h3>${c.formalName?`<p class="form-note">正式名称：${esc(c.formalName)}</p>`:''}${scheduleBadge(c)}<p>${uiIcon('person')}${esc(c.teacher)} · ${esc(c.room)}</p><p>${uiIcon('calendar')}${date} · 第${week}教学周 · 周${weekdays[c.day-1]} · ${c.slot*2-1}–${c.slot*2}节</p><p class="form-note">课程开课周：${c.weeks.join('、')}</p>${c.notice?`<p class="notice">${esc(c.notice)}</p>`:""}${learningBadge(c.id,date)}</header>${courseNotice(date)}
 <div class="course-tabs" role="tablist" aria-label="课程详情内容">${[['plan','学习计划'],['record','课堂记录'],['tasks','相关任务']].map(([tab,label])=>`<button type="button" role="tab" id="course-tab-${tab}" aria-controls="course-panel-${tab}" aria-selected="${tab===activeTab}" tabindex="${tab===activeTab?0:-1}" data-action="course-tab" data-tab="${tab}" data-id="${esc(key)}" class="${tab===activeTab?'active':''}">${label}</button>`).join('')}</div>
 <section class="learning-section course-panel" id="course-panel-plan" role="tabpanel" aria-labelledby="course-tab-plan" ${activeTab!=='plan'?'hidden':''}><div class="card-head"><h3>本节学习计划</h3>${btn('编辑学习计划 · 流程画布','course-flow',key,'small primary')}${btn('简表编辑','course-plan-edit',key,'small')}</div>${hasLearningGoals(p)?`${p.topic?`<div class="topic-block"><h4>本节主题</h4><p class="learning-topic">${esc(p.topic)}</p></div>`:''}<h4>课前问题</h4>${learningList(p.preQuestions)}<div class="learning-line minimum"><h4>保底线 · 最少拿走什么</h4>${learningList(p.minimumGoals)}</div><div class="learning-line standard"><h4>达标线 · 本节主要目标</h4>${learningList(p.standardGoals)}</div><div class="learning-line stretch"><h4>进阶线 · 时间与状态允许时</h4>${learningList(p.stretchGoals)}</div>`:'<div class="course-plan-empty"><p class="empty">本节尚未制定学习目标。</p><p>带着一个问题走进课堂，留下自己的理解。</p></div>'}<p class="form-note">进阶线可留空，不要求完成。课程内容由你填写，不自动推测章节。</p><div class="actions section-gap">${btn('复制本节课程给ChatGPT','course-copy',key,'small')}</div></section>
 <section class="learning-section course-panel" id="course-panel-record" role="tabpanel" aria-labelledby="course-tab-record" ${activeTab!=='record'?'hidden':''}><div class="card-head"><h3>本次课堂学习记录</h3>${btn('记录本次学习','course-reflect',key,'small primary')}</div><p class="meta">自评：${learningLevels[p.levelReached]} · 自评与学习证据分别保留</p><h4>本次实际完成 / 学会的内容</h4><p class="text-line record-content">${esc(p.reflection||'尚未记录。可以写今天学了什么、完成哪道题，以及你自己的解释。')}</p><h4>学习证据</h4>${learningList(p.evidence.map(k=>learningEvidence[k]))}<h4>本节最大问题 / 卡点</h4><p class="text-line record-content">${esc(p.unresolvedProblem||'尚未填写')}</p><p class="form-note">听过、花过时间不自动代表掌握。保存本节记录不会增加自主投入时长。</p>${saved?`<div class="actions section-gap">${btn('复制本次学习记录','course-copy-record',saved.id,'small')}</div>`:''}</section>
 <section class="learning-section course-panel" id="course-panel-tasks" role="tabpanel" aria-labelledby="course-tab-tasks" ${activeTab!=='tasks'?'hidden':''}><div class="card-head"><h3>相关任务</h3></div>${task?`<article class="related-task"><span class="badge">${statusLabel[task.status]}</span><h4>${esc(task.title)}</h4><p class="meta">${task.date} · 预计 ${task.estimatedMinutes} 分钟 · 已记录 ${G.taskMinutes(state,task.id)} 分钟</p></article>`:'<p class="empty">这节课还没有关联的课后复盘任务。</p>'}${saved?btn(task?'查看课后复盘任务':'创建课后复盘任务','course-review-task',saved.id,'primary course-task-button'):'<p class="form-note">保存学习计划或本次学习记录后，可以创建关联的课后复盘任务。</p>'}<p class="form-note">课堂是固定时间；课后的实际投入按发生日期单独记录。</p></section>
 ${c.optional?optionalCard(C.optionalForWeek(week).find(x=>x.id===c.id),date,true):''}</div>`);
 dialog.classList.add('course-dialog');
}
function activateCourseTab(tab,focus=false){if(!['plan','record','tasks'].includes(tab))return;dialog.querySelectorAll('[data-action="course-tab"]').forEach(button=>{const active=button.dataset.tab===tab;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;if(active&&focus)button.focus();});dialog.querySelectorAll('.course-panel').forEach(panel=>panel.hidden=panel.id!=='course-panel-'+tab);}
function learningArea(label,name,value,max=10000){return `<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" maxlength="${max}">${esc(value)}</textarea></div>`;}
function courseLearningForm(key,reflectionOnly=false){
 const {course:c,date,week,plan:p}=courseSession(key),hidden=`<input type="hidden" name="session" value="${esc(key)}"><p class="form-note">${esc(c.name)} · ${date} · 第${week}教学周</p>`;
 const body=reflectionOnly?`${learningArea('本次实际完成 / 学会的内容','reflection',p.reflection)}<fieldset class="learning-checks"><legend>本节学习证据（可独立勾选）</legend>${Object.entries(learningEvidence).map(([v,label])=>`<label class="check"><input type="checkbox" name="evidence" value="${v}" ${p.evidence.includes(v)?'checked':''}>${label}</label>`).join('')}</fieldset>${learningArea('本节最大问题 / 卡点','unresolvedProblem',p.unresolvedProblem)}${select('本节自评状态','levelReached',Object.entries(learningLevels),p.levelReached)}<p class="form-note">你可以只记成果或卡点，不必先写计划。达到保底不会自动升级为达标；未完成进阶没有失败评价。</p>`:
 `${input('本节主题','topic',p.topic,'text','maxlength="500"')}<p class="form-note">以下每行填写一项，可留空。建议保底1—3项、达标3—6项，进阶可选。</p>${learningArea('课前问题（每行一项）','preQuestions',p.preQuestions.join('\n'),51000)}${learningArea('保底线（每行一项）','minimumGoals',p.minimumGoals.join('\n'),51000)}${learningArea('达标线（每行一项）','standardGoals',p.standardGoals.join('\n'),51000)}${learningArea('进阶线（可选，每行一项）','stretchGoals',p.stretchGoals.join('\n'),51000)}`;
 modal(reflectionOnly?'记录本次学习':'编辑本节学习计划',hidden+`<div class="learning-form">${body}</div>${!reflectionOnly?'<button type="submit" name="openCanvas" value="1">保存并进入流程画布</button>':''}`,reflectionOnly?'course-reflection':'course-plan');
}
function courseHistory(){
 const all=state.courseLearningPlans.slice().sort((a,b)=>b.date.localeCompare(a.date)||C.courses.find(c=>c.id===a.courseId).slot-C.courses.find(c=>c.id===b.courseId).slot),names=[...new Set(all.map(p=>C.courses.find(c=>c.id===p.courseId).name))];
 if(!names.includes(courseHistoryFilter))courseHistoryFilter='';
 const rows=all.filter(p=>!courseHistoryFilter||C.courses.find(c=>c.id===p.courseId).name===courseHistoryFilter);
 return `<section class="card section" id="course-learning-history"><div class="card-head"><h2>课程学习记录</h2><small>按每次上课独立保存</small></div><p class="form-note">从今日课程或本周课表打开课程，记录本次完成内容。这里保留计划、成果与卡点，便于以后查找和复盘。</p>${all.length?`<div class="filters"><label for="course-history-filter">按课程筛选</label><select id="course-history-filter" aria-label="按课程筛选"><option value="">全部课程</option>${names.map(n=>`<option value="${esc(n)}" ${n===courseHistoryFilter?'selected':''}>${esc(n)}</option>`).join('')}</select><small>共 ${rows.length} 次</small></div>${rows.map(p=>{const c=C.courses.find(c=>c.id===p.courseId);return `<article class="course-history-row" data-course-plan-id="${esc(p.id)}"><div class="card-head"><h3>${esc(c.name)}</h3>${learningBadge(p.courseId,p.date)}</div><p class="meta">${p.date} · 第${p.week}教学周 · 周${weekdays[c.day-1]} ${c.slot*2-1}–${c.slot*2}节</p>${p.topic?`<p class="learning-topic">${esc(p.topic)}</p>`:''}<p class="text-line learning-preview">${esc(p.reflection||'尚未填写本次实际完成内容')}</p>${p.unresolvedProblem?`<p class="text-line learning-preview">卡点：${esc(p.unresolvedProblem)}</p>`:''}<div class="actions">${btn('查看 / 编辑','course-history-open',p.id,'small')}${btn('复制本次学习记录','course-copy-record',p.id,'small')}</div></article>`;}).join('')}`:'<p class="empty">还没有课程学习记录。</p>'}</section>`;
}
function learningFacts(){const s=G.courseLearningStats(state,selected,new Date().toISOString());return `<section class="card section" data-testid="course-learning-facts"><div class="card-head"><h2>本周课程复盘</h2><small>仅统计已发生课程</small></div><div class="learning-facts">${[['已复盘',s.reviewedCount,'reviewed'],['自评保底',s.minimumCount,'minimum'],['自评达标',s.standardCount,'standard'],['有卡点',s.blockedCount,'blocked']].map(([label,value,id])=>`<div><small>${label}</small><strong data-learning-count="${id}">${value}<small> 次</small></strong></div>`).join('')}</div><p class="form-note">填写成果、证据、卡点或自评后计为已复盘。三档自评分别计数，不自动升级；卡点可同时存在，不计算掌握率。</p></section>`;}
function copyCourseText(){const t=document.querySelector('#course-copy-text');t.focus();t.select();if(navigator.clipboard?.writeText)navigator.clipboard.writeText(t.value).then(()=>toast('已复制，由你决定是否发送给ChatGPT')).catch(()=>toast('文本已选中，可按 Ctrl+C 或长按复制'));else{try{toast(document.execCommand('copy')?'已复制':'文本已选中，可按 Ctrl+C 或长按复制');}catch(e){toast('文本已选中，可按 Ctrl+C 或长按复制');}}}
function courseCopy(title,text){modal(title,`<p class="form-note">仅生成本地文本，不向任何服务发送。复制失败时可直接选择下方文字。</p><textarea id="course-copy-text" class="review-text" aria-label="课程复制文本" readonly>${esc(text)}</textarea><div class="dialog-actions">${btn('复制文本','copy-course-text','','primary')}</div>`);copyCourseText();}
function coursePrompt(key){const {course:c,date,week,plan:p,saved}=courseSession(key);return `【课程】\n${c.name}\n【教学周】\n第${week}周\n【本节时间】\n${date} 周${weekdays[c.day-1]} ${c.slot*2-1}–${c.slot*2}节\n【本节主题】\n${p.topic||'尚未填写，请先询问我本节讲授内容'}\n\n${saved?G.courseLearningText(state,saved.id)+'\n\n':''}请根据我提供的本节内容，帮我制定：\n1. 课前需要知道什么\n2. 本节最重要的问题\n3. 保底学习目标\n4. 达标学习目标\n5. 进阶学习目标（可选）\n6. 如何验证自己是否真正掌握\n\n不要把所有知识都列成重点。若主题、教材或课堂内容不足，请先向我确认，不要编造老师讲授的章节。若已有本次成果和卡点，请先据此复盘，再建议下一步。`;}
function errorBanner(message){const e=document.querySelector('#storage-error');e.hidden=false;e.textContent=message;}
function toast(message){const e=document.querySelector('#status');e.textContent=message;e.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.hidden=true,4200);}
try {lastRaw=localStorage.getItem(KEY);state=lastRaw?G.upgradeState(JSON.parse(lastRaw)):G.newState();G.validateState(state);}
catch(e){state=G.newState();blocked=true;errorBanner('本机数据无法读取。已停止写入，请从数据管理导出原始数据或导入有效备份。');}
function persist(next, recovery=false){
 if(blocked&&!recovery) throw new Error('当前存储不可写，请先在数据管理恢复有效备份。');
 if(!recovery&&localStorage.getItem(KEY)!==lastRaw) throw new Error('另一窗口已更新数据。请刷新此页后再操作，避免覆盖。');
 G.validateState(next);const raw=JSON.stringify(next);localStorage.setItem(KEY,raw);lastRaw=raw;state=next;blocked=false;
 document.querySelector('#storage-error').hidden=true;
}
function change(action,payload){const next=clone(state);G.mutate(next,action,payload);persist(next);}
function safe(fn){try{fn();}catch(e){toast(e.message);if(/quota|storage|存储|窗口|写入/i.test(e.message))errorBanner('保存失败，刚才的修改未写入：'+e.message);}}
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null)errorBanner('另一窗口的数据已变化。请刷新后继续，以免覆盖。');});
function heading(title,sub,actions=''){return `<header class="page-head"><div><h1>${title}</h1><p class="muted">${sub}</p></div><div class="header-actions">${actions}${btn('数据','data','','small data-link-mobile')}</div></header>`;}
function weekLabel(date){const w=G.teachingWeek(date);return w<1?'教学周尚未开始':w>20?'本学期已结束':`第 ${w} 教学周 / 共20周`;}
function weekPicker(){return `<div class="week-switch">${btn('‹','prev-week','','small')}<label>第 <input aria-label="教学周" id="week-number" type="number" min="1" max="20" value="${Math.max(1,Math.min(20,G.teachingWeek(selected)))}"> 周</label>${btn('›','next-week','','small')}${btn('回到本周','current-week','','small')}<small>${selected} — ${G.addDays(selected,6)}</small></div>`;}
function taskCard(t,main=false){return `<div class="${main?'hero-task':'task-row'}" data-task-id="${esc(t.id)}" ${main?'data-testid="main-task"':'data-testid="secondary-task"'}>
 ${main?`<span class="badge">今日主任务${t.status==='done'?' · 已完成':''}</span>`:''}<h3>${esc(t.title)}</h3>
 <p class="meta">${esc(cat(t.category))} · 预计 ${t.estimatedMinutes} 分钟 · 已投入 ${G.taskMinutes(state,t.id)} 分钟 · ${statusLabel[t.status]}</p>
 ${learningTaskLink(t)}${t.evidence?`<p class="evidence">完成证据 / 卡点：${esc(t.evidence)}</p>`:''}
 <div class="actions">${t.status!=='done'?btn('完成','complete',t.id,'small primary'):''}${btn('记投入','log',t.id,'small')}${btn('流程编排','task-map',t.id,'small')}${btn('编辑','task-edit',t.id,'small')}${t.status!=='done'?btn('延期到明天','postpone',t.id,'small'):''}</div></div>`;}
function progressCards(stats){return stats.comparison.length?`<div class="goals">${stats.comparison.map(t=>{
 const percent=t.targetMinutes>0?t.actualMinutes/t.targetMinutes*100:null;
 return `<div class="goal" data-task-progress="${esc(t.id)}"><p class="goal-name">${esc(t.label)}</p><p class="goal-amount">${fmt(t.actualMinutes)}<small> / ${fmt(t.targetMinutes)}h</small></p><progress aria-label="${esc(t.label)}投入进度" max="100" value="${percent===null?0:Math.min(100,percent)}"></progress><p class="goal-note">${statusLabel[t.status]} · ${percent===null?'未设预计时长':Math.round(percent)+'% 已投入'}${percent>100?' · 超出预计':''}</p></div>`;
 }).join('')}</div><p class="form-note">按当前安排在本周的任务统计；进度条表示实际投入 / 预计耗时，任务完成以你确认的状态为准。</p>`:'<p class="empty">本周还没有安排任务。新建任务后，这里会显示你的任务和投入进度。</p>';}
function optionalCard(c,date,insideDetail=false){const a=state.attendance.find(x=>x.date===date&&x.courseId===c.id);return `<div class="optional"><div class="actions"><span class="badge warm">可选旁听</span><strong>${esc(c.name)}</strong>${!insideDetail?btn("学习计划 / 记录","course-open",date+"|"+c.id,"small"):""}</div><p class="meta">${date} · ${(c.slot-1)*2+1}–${c.slot*2}节 · ${esc(c.room)} · ${esc(c.teacher)}</p>${courseNotice(date)}${c.warning?`<p class="notice">${esc(c.warning)}</p>`:''}${c.conflict?`<p class="muted">与${esc(c.conflictNames.join('、'))}冲突，正式课优先。</p>`:`<div class="actions">${a?`<span class="badge">${a.attended?'已参加':'计划参加'} · 预留${a.plannedMinutes}分钟</span>`:''}${!a?.attended?btn(a?'调整计划':'计划参加','attendance-plan',date+'|'+c.id,'small'):''}${btn(a?.attended?'编辑投入':'记录参加','attendance-attend',date+'|'+c.id,'small')}${a?btn(a.attended?'取消时间预留':'取消计划','attendance-cancel',date+'|'+c.id,'small'):''}</div>`}</div>`;}
function workbenchMetrics(d,formal){
 const tasks=state.tasks.filter(t=>t.date===d),done=tasks.filter(t=>t.status==='done').length;
 const minutes=state.logs.filter(l=>l.date===d).reduce((n,l)=>n+l.minutes,0);
 const rounds=(state.timerBoard?.records||[]).filter(r=>{const t=new Date(r.finishedAt);return t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0')===d;});
 const courses=formal.filter(c=>!['occupied','excused'].includes(c.attendanceStatus)).length;
 return `<section class="wb-metrics section" aria-label="今日概览"><button class="wb-metric" data-action="all-tasks"><span class="wb-metric-name">${uiIcon('target')}今日任务</span><strong>${done}<small> / ${tasks.length} 项</small></strong><span>已完成 / 今日安排</span></button><button class="wb-metric" data-page="records"><span class="wb-metric-name">${uiIcon('book')}已确认投入</span><strong>${minutes}<small> 分钟</small></strong><span>按今天的实际投入记录</span></button><button class="wb-metric" data-page="focus"><span class="wb-metric-name">${uiIcon('person')}已收尾专注</span><strong>${rounds.length}<small> 轮</small></strong><span>计时记录 · 不代表任务完成</span></button><button class="wb-metric" data-action="go-schedule"><span class="wb-metric-name">${uiIcon('calendar')}今日课程</span><strong>${courses}<small> 堂</small></strong><span>按现有课表需参加的课程</span></button></section>`;
}
function quickCategories(){return categories.filter(c=>c.id!=='stocks'||!state.settings.hideStocks);}
function dayLabel(d){const t=G.today(),rel=d===t?'今天 ':d===G.addDays(t,1)?'明天 ':d===G.addDays(t,2)?'后天 ':'';return rel+Number(d.slice(5,7))+'/'+Number(d.slice(8))+' 周'+weekdays[(new Date(d+'T12:00:00').getDay()+6)%7]+(d.slice(0,4)!==t.slice(0,4)?' · '+d.slice(0,4)+'年':'')+(d<t?'（早于今天）':'');}
// Same defaults as the full task form: today, 学校专业课, 30 minutes, high priority.
function quickResult(){const r=QA.parse(quick.text,G.today(),{category:!quick.category,minutes:!quick.minutes,categories:quickCategories().map(c=>c.id)});
 return {title:r.title,date:r.date||G.today(),category:quick.category||r.category||'school',estimatedMinutes:quick.minutes?Number(quick.minutes):r.minutes??30,categoryDefault:!quick.category&&!r.category,minutesDefault:!quick.minutes&&r.minutes===null};}
function quickHint(){if(!quick.text.trim())return {text:'可以把日期和时长一起写上，例如“明天 复习模电 45分钟”。按回车添加。',error:false};
 try{const q=quickResult();if(!q.title)return {text:`已识别：${dayLabel(q.date)} · ${q.estimatedMinutes} 分钟${q.minutesDefault?'（默认）':''}。再写下要做的事。`,error:false};return {text:`将添加「${q.title}」 · ${dayLabel(q.date)} · ${cat(q.category)}${q.categoryDefault?'（默认分类）':''} · 预计 ${q.estimatedMinutes} 分钟${q.minutesDefault?'（默认）':''}`,error:false};}
 catch(e){return {text:e.message,error:true};}}
function quickPreview(){const hint=document.querySelector('#qa-hint');if(!hint)return;const h=quickHint();hint.textContent=h.text;hint.classList.toggle('is-error',h.error);}
function quickComposer(){if(quick.category&&!quickCategories().some(c=>c.id===quick.category))quick.category='';const h=quickHint();return `<form class="qa-composer" data-form="quick-task" autocomplete="off"><label class="qa-label" for="qa-text">一句话新建任务</label><input id="qa-text" name="text" type="text" maxlength="200" value="${esc(quick.text)}" placeholder="写下要做的事，例如：明天 复习模电 45分钟" aria-describedby="qa-hint" enterkeyhint="done"><p id="qa-hint" class="qa-hint${h.error?' is-error':''}">${esc(h.text)}</p><div class="qa-row"><select id="qa-category" aria-label="分类"><option value="">分类：按文字识别</option>${quickCategories().map(c=>`<option value="${esc(c.id)}" ${quick.category===c.id?'selected':''}>${esc(c.label)}</option>`).join('')}</select><select id="qa-minutes" aria-label="预计耗时"><option value="">时长：按文字识别</option>${[15,25,30,45,60,90,120].map(m=>`<option value="${m}" ${quick.minutes===String(m)?'selected':''}>${m} 分钟</option>`).join('')}</select>${btn('详细填写','quick-task-form','','quiet small')}<span class="qa-grow"></span><button type="submit" class="qa-send" aria-label="添加任务"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 19V5M5 12l7-7 7 7"/></svg></button></div><p class="form-error" role="alert"></p></form>`;}
function workbenchMenu(open){document.body.classList.toggle('wb-nav-open',open);const toggle=document.querySelector('#wb-menu-toggle');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'关闭导航':'展开导航');}
function renderToday(){const d=G.today(),tw=G.teachingWeek(d),f=G.focusTasks(state,d),stats=window.TGDashboard.build(state,G.weekStart(d)),formal=C.forDay(tw,todayDay());
const active=state.timerBoard?.active;
return `<header class="wb-hero section"><div><p class="eyebrow">${d.replaceAll('-',' / ')} · 星期${weekdays[todayDay()-1]} · ${weekLabel(d)}</p><h1>今天，从哪一件事开始？</h1><p class="muted">定一个目标，留一段时间，把今天的进展看清楚。</p></div><div class="wb-hero-actions"><button type="button" data-page="timer" class="primary">${active?'回到当前专注':'准备开始专注'} <span aria-hidden="true">→</span></button>${btn('记录实际投入','log')}</div></header>`+quickComposer()+workbenchMetrics(d,formal)+
 `<div class="layout today-grid section"><section class="card today-focus"><div class="card-head"><h2>${uiIcon('target')}今日主任务</h2><small>先推进最重要的一件事</small></div>
 ${f.main?taskCard(f.main,true):`<div class="empty-box"><h3>为今天选一个主任务</h3><p>先明确最想推进的一个结果。</p>${btn('选择主任务','choose-main','','primary')}</div>`}
 ${f.secondary.length?'<p class="secondary-label">其他重点 · 最多2个</p>':''}${f.secondary.map(t=>taskCard(t)).join('')}${!f.secondary.length?'<p class="empty secondary-empty">次要重点留白也可以。</p>':''}
 <div class="actions focus-footer">${f.main?btn('更换主任务','choose-main','','small'):''}${btn('查看全部任务','all-tasks','','quiet')}</div></section><section class="card today-courses"><div class="card-head"><h2>${uiIcon('book')}今日课程 <small>（${formal.filter(c=>!['occupied','excused'].includes(c.attendanceStatus)).length}堂需参加）</small></h2>${btn('全部课程 '+uiIcon('arrow'),'go-schedule','','quiet small')}</div>${courseNotice(d)}${formal.length?formal.map(c=>`<button type="button" data-action="course" data-id="${c.id}" data-date="${d}" data-attendance-status="${c.attendanceStatus||'normal'}" class="course-row course-today course-accent-${c.slot}"><span class="course-slot">${(c.slot-1)*2+1}–${c.slot*2}节</span><div class="course-brief"><p>${esc(courseTitle(c))}${K.annotation(d).kind==='leave'?'<span class="calendar-tag leave">建模请假安排</span>':''}</p>${scheduleBadge(c)}<small>${esc(c.room)} · ${esc(c.teacher)}</small></div><span class="course-learning-state">${learningBadge(c.id,d)}</span></button>`).join(''):'<p class="empty">今天没有固定课程。</p>'}
 ${eventNotices(tw)}<p class="form-note">正式课程优先 · 按节次显示，临时调课以学校通知为准。</p></section></div>
 <section class="card section today-progress"><div class="card-head"><h2>本周任务进度</h2><span class="progress-summary">已记录 <strong>${fmt(stats.totalMinutes)}h</strong> · 完成 ${stats.completedCount}/${stats.taskCount} 项任务</span></div>${progressCards(stats)}<div class="actions progress-footer">${btn('安排本周','go-week','','quiet')}${btn('查看完整数据看板 '+uiIcon('arrow'),'go-dashboard','','quiet')}</div></section>
 ${weekCalendar(G.weekStart(d),true)}<p class="quiet-motto">更好的自己，从每一个今天开始。</p>`;}
function eventNotices(w){return C.events.filter(e=>e.weeks.includes(w)).map(e=>`<p class="notice">${esc(e.name)} · ${esc(e.notice||'具体节次待确认')}</p>`).join('');}
function calendarBadge(date){const a=K.annotation(date);return a.label?`<span class="calendar-tag ${esc(a.kind)}" title="${esc(a.note)}">${esc(a.label)}</span>`:'';}
function courseNotice(date){const a=K.annotation(date);if(!a.label)return '';return `<p class="course-notice ${esc(a.kind)}">${esc(a.label)} · ${esc(a.note)}</p>`;}
function eventTime(iso){return Number(iso.slice(5,7))+'月'+Number(iso.slice(8,10))+'日 '+iso.slice(11,16);}
function modelingCard(e){const status=K.eventStatus(e.id),label={upcoming:'即将开始',active:'进行中',ended:'已结束'}[status];return `<article class="calendar-event" data-event-id="${esc(e.id)}"><div class="card-head"><h3>${esc(e.name)}</h3><span class="badge ${status==='active'?'':'warm'}">${label}</span></div><p><strong>${eventTime(e.start)} — ${eventTime(e.end)}</strong></p><p>地点：${esc(e.location)} · 老师安排请假（你提供的安排）</p><p class="form-note">9月14日00:00即结束，不包含周一白天。活动时段包含休息，不自动记为学习时长；实际投入请在「记录」填写。</p></article>`;}
function weekCalendar(monday,compact=false){const dates=G.weekDates(monday),last=dates[6],events=K.events.filter(e=>e.start.slice(0,10)<=last&&e.end.slice(0,10)>=monday&&dates.some(d=>K.eventsForDate(d).some(x=>x.id===e.id)));
const special=dates.filter(d=>K.holidayForDate(d)),unknown=dates.some(d=>d.startsWith('2027'));
const holidayGroups=[];for(const date of special){const h=K.holidayForDate(date),last=holidayGroups[holidayGroups.length-1];if(last&&last.label===h.label&&G.addDays(last.end,1)===date)last.end=date;else holidayGroups.push({start:date,end:date,label:h.label});}
const holidayRows=compact?holidayGroups.map(g=>`<div class="calendar-day"><strong>${g.start.slice(5)}${g.end!==g.start?'—'+g.end.slice(5):''}</strong><div>${calendarBadge(g.start)}<p class="form-note">学校停补课安排待核实，基础课表保留。</p></div></div>`).join(''):special.map(d=>{const h=K.holidayForDate(d);return `<div class="calendar-day"><strong>${d}</strong><div>${calendarBadge(d)}<p class="form-note">${esc(h.note)}</p></div></div>`;}).join('');
if(compact&&!events.length&&!special.length&&!unknown)return '';
return `${compact?'<details class="card section calendar-panel calendar-compact"><summary>本周特殊安排 <span class="muted">'+(events.length+holidayGroups.length)+'项日历提示'+(unknown?' · 含待核实安排':'')+'</span></summary><div class="calendar-fold-content">':'<section class="card section calendar-panel"><div class="card-head"><h2>节假日与特殊安排</h2><small>本地日历 · 按北京时间</small></div>'}${events.map(modelingCard).join('')}${holidayRows}${unknown?'<p class="notice">2027年完整放假调休安排未核实；元旦仅标法定日期。未标记的日期不代表已确认正常上课。</p>':''}${!events.length&&!special.length&&!unknown?'<p class="muted">本周没有已录入的特殊日程。</p>':''}${compact?'':`<details class="section-gap"><summary>本学期已核对的节假日</summary><p>中秋：2026年9月25日—27日</p><p>国庆：2026年10月1日—7日</p><p>全国调休上班：9月20日、10月10日</p><p>元旦：2027年1月1日（法定日期，完整调休待核实）</p><p class="form-note">法定放假调休与学校校历分开处理。原课表保留并标注“学校安排待核对”，不会自动删课、补课或延期个人任务。</p><p class="form-note">来源：国务院办公厅国办发明电〔2025〕7号、2024年修订《全国年节及纪念日放假办法》；2026-09-07核对。离线数据，不自动联网更新。</p></details>`}${compact?'</div></details>':'</section>'}`;}
function scheduleText(monday){const original=C.weekText(G.teachingWeek(monday));return original.split('\n').map(line=>{const day=/^周([一二三四五六日])\s/.exec(line);if(!day)return line;const a=K.annotation(G.addDays(monday,weekdays.indexOf(day[1])));return a.label?`${line}【${a.label}；${a.note}】`:line;}).join('\n')+'\n\n节假日与个人特殊安排：\n'+K.weekText(monday);}
function timetable(){const w=G.teachingWeek(selected),formal=C.forWeek(w),optional=[];return `<section class="card section"><div class="card-head"><h2>本周课表</h2><small>点击课程查看详情</small></div><p class="form-note" data-testid="schedule-profile">${esc(C.personalProfile.name)} · ${esc(C.personalProfile.className)} · 第一组 · 2026—2027 学年第一学期</p><p class="table-hint">左右滑动查看一周课程。</p><div class="table-scroll"><table class="timetable"><thead><tr><th>节次</th>${weekdays.map((x,i)=>`<th class="${G.addDays(selected,i)===G.today()?'today-col':''}">周${x}<br><small>${G.addDays(selected,i).slice(5)}</small>${calendarBadge(G.addDays(selected,i))}</th>`).join('')}</tr></thead><tbody>${[1,2,3,4,5].map(slot=>`<tr><th>${slot*2-1}–${slot*2}</th>${weekdays.map((_,i)=>`<td class="${G.addDays(selected,i)===G.today()?'today-col':''}">${formal.filter(c=>c.day===i+1&&c.slot===slot).map(c=>`<button data-action="course" data-id="${c.id}" data-date="${G.addDays(selected,i)}" data-attendance-status="${c.attendanceStatus||'normal'}" class="course-cell">${esc(courseTitle(c))}<br><small>${esc(c.room)}</small>${scheduleBadge(c)}${learningBadge(c.id,G.addDays(selected,i))}${K.annotation(G.addDays(selected,i)).kind==='leave'?'<span class="calendar-tag leave">建模请假安排</span>':''}</button>`).join('')}${optional.filter(c=>c.day===i+1&&c.slot===slot).map(c=>`<button data-action="course" data-id="${c.id}" data-date="${G.addDays(selected,i)}" class="course-cell optional-cell ${c.conflict?'conflict':''}">👀 旁听 · ${esc(c.name)}<br><small>${c.conflict?'与正式课冲突':esc(c.room)}</small>${learningBadge(c.id,G.addDays(selected,i))}</button>`).join('')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${eventNotices(w)}${C.pendingNotices.map(n=>`<p class="notice" data-schedule-pending="${esc(n.id)}">【待确认】${esc(n.notice)}</p>`).join('')}<p class="form-note">本人实验优先；被占用的理论课保留学习记录入口。课程按节次显示。</p></section>`;}
function renderSchedule(){return heading('我的课表','按教学周查看课程，点击课程卡片继续学习计划与课堂记录。')+`<div class="section">${weekPicker()}</div>${timetable()}${weekCalendar(selected)}`;}
function renderWeek(){const s=window.TGDashboard.build(state,selected),filteredTasks=state.tasks.filter(t=>taskStatusFilter==='all'||t.status===taskStatusFilter);return heading('本周安排','目标属于这一周，历史记录会保留。',btn('＋ 新建任务','task-new','','primary'))+
 `<div class="section">${weekPicker()}</div><details class="card section"><summary>本学期方向</summary><p class="text-line">${esc(state.settings.direction||'考研准备为长期主线，兼顾本学期正式课程。')}</p><p class="meta">当前重点：${esc(state.settings.focus||'尚未填写')}</p><p class="meta">暂缓事项：${esc(state.settings.defer||'尚未填写')}</p>${btn('编辑方向','settings','','small')}</details>
 <section class="card section"><div class="card-head"><h2>本周任务进度</h2><span class="badge">完成 ${s.completedCount} / ${s.taskCount} 项</span></div><p class="form-note">任务预计 ${fmt(s.targetTotalMinutes)}h · 已记录 ${fmt(s.totalMinutes)}h。新建或编辑任务后自动更新。</p>${progressCards(s)}</section>
 
 <section class="card" id="all-tasks"><div class="card-head"><h2>任务列表</h2><small>包括历史与未来安排</small></div><div class="task-filters" role="group" aria-label="任务状态筛选">${[['all','全部'],['doing','进行中'],['done','已完成']].map(([value,label])=>`<button type="button" data-action="task-filter" data-filter="${value}" aria-pressed="${taskStatusFilter===value}" class="${taskStatusFilter===value?'active':''}">${label}</button>`).join('')}</div>${filteredTasks.length?filteredTasks.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(t=>`<div class="task-row task-list-item ${t.status==='done'?'task-is-done':''}" data-task-id="${esc(t.id)}"><div class="titleline"><strong>${esc(t.title)}</strong><span class="badge ${state.mainByDate[t.date]===t.id?'main-tag':''}">${state.mainByDate[t.date]===t.id?'主任务 · ':''}${statusLabel[t.status]}</span></div><p class="meta">${t.date} · ${esc(cat(t.category))} · 优先级${priorityLabel[t.priority]} · 预计${t.estimatedMinutes}分钟 / 实际${G.taskMinutes(state,t.id)}分钟</p>${learningTaskLink(t)}${t.notes?`<p class="text-line">${esc(t.notes)}</p>`:''}${t.evidence?`<p class="evidence">${esc(t.evidence)}</p>`:''}<div class="actions">${t.date===G.today()?btn('设为今日主任务','set-main',t.id,'small'):''}${t.status!=='done'?btn('完成','complete',t.id,'small primary'):''}${btn('记投入','log',t.id,'small')}${btn('流程编排','task-map',t.id,'small')}${btn('编辑','task-edit',t.id,'small')}${btn('延期到明天','postpone',t.id,'small')}${btn('删除','task-delete',t.id,'small danger')}</div></div>`).join(''):`<p class="empty">${state.tasks.length?'这个筛选下暂无任务。':'还没有任务。先添加今天最想推进的一件事。'}</p>`}</section>`;}
function renderRecords(){return heading('学习记录','时长代表投入，自己的理解代表这次学习的成果。',btn('＋ 记投入','log','','primary'))+courseHistory()+` <section class="card"><div class="card-head"><h2>投入记录</h2><small>按实际发生日期保存，关联任务后计入任务进度</small></div>${state.logs.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(l=>`<div class="list-row" data-log-id="${esc(l.id)}"><div><strong>${esc(cat(l.category))} · ${l.minutes}分钟</strong><p class="meta">${l.date}${l.taskId?' · '+esc(state.tasks.find(t=>t.id===l.taskId)?.title||'原任务已删除'):''}</p>${l.evidence?`<p class="text-line">${esc(l.evidence)}</p>`:''}</div><div class="actions">${btn('编辑','log-edit',l.id,'small')}${btn('删除','log-delete',l.id,'small danger')}</div></div>`).join('')||'<p class="empty">还没有投入记录。未完成的任务也可以先记录已付出的时间。</p>'}</section>`;}
function renderDashboard(){const data=window.TGDashboard.build(state,selected,G.today());return heading('数据看板','时间投向哪里，下一周如何分配。','<button data-page="focus">专注统计 ↗</button>')+`<div class="section">${weekPicker()}</div><p class="dashboard-scope">第${G.teachingWeek(selected)}教学周 · ${selected} — ${G.addDays(selected,6)} · ${selected>G.today()?'未来周，尚无已发生投入':'实际统计截至 '+(G.addDays(selected,6)<G.today()?G.addDays(selected,6):G.today())}。图表仅来自你的记录。</p>`+learningFacts()+window.TGDashboardView.render(data);}
function render(){const quickFocused=document.activeElement?.id==='qa-text';document.body.dataset.page=page;document.querySelector('#wb-location').textContent=({today:'今日工作台',week:'本周安排',schedule:'我的课表',timer:'任务计时看板',focus:'专注统计',dashboard:'投入看板',records:'学习记录'})[page]||'今日工作台';document.querySelectorAll('.sidebar [data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});app.innerHTML=page==='focus'?window.TGFocusStats.render(state,focusRange):page==='timer'?window.TGTimerView.render():page==='today'?renderToday():page==='week'?renderWeek():page==='schedule'?renderSchedule():page==='dashboard'?renderDashboard():page==='records'?renderRecords():renderToday();if(quickFocused){const n=document.querySelector('#qa-text');if(n){n.focus();n.setSelectionRange(n.value.length,n.value.length);}}}
function modal(title,body,form='',button='保存'){dialog.classList.remove('course-dialog');document.querySelector('#dialog-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${btn('×','close','','')}</div>${form?`<form data-form="${form}">${body}<p class="form-error" role="alert"></p><div class="dialog-actions">${btn('取消','close','','')}<button type="submit" class="primary">${button}</button></div></form>`:body}`;dialog.showModal();}
function agentHint(){return '';}
function taskForm(t,coursePlan){if(!t&&coursePlan){const c=C.courses.find(c=>c.id===coursePlan.courseId);t={title:('课后复盘：'+c.name+(coursePlan.topic?' · '+coursePlan.topic:'')).slice(0,150),category:'school',date:coursePlan.date,estimatedMinutes:30,priority:'medium',status:'todo',coursePlanId:coursePlan.id};}modal(t?.id?'编辑任务':'新建任务',`<input type="hidden" name="id" value="${esc(t?.id||'')}"><input type="hidden" name="coursePlanId" value="${esc(t?.coursePlanId||'')}">${t?.coursePlanId?learningTaskLink(t):''}<div class="form-grid">${input('任务名称','title',t?.title||'','text','required maxlength="150" class="full"')}${catSelect(t?.category||'school')}${input('安排日期','date',t?.date||G.today(),'date','required')}${input('预计耗时（分钟）','estimatedMinutes',t?.estimatedMinutes??30,'number','min="0" max="1440" step="1" required')}${select('优先级','priority',Object.entries(priorityLabel),t?.priority||'high')}${select('状态','status',Object.entries(statusLabel),t?.status||'todo')}${textarea('备注（可选）','notes',t?.notes)}${textarea('完成证据 / 未解决问题（可选）','evidence',t?.evidence)}</div>${agentHint(t?.category||'school')}<p class="form-note">实际耗时由投入记录汇总；完成任务不会自动填入预计时间。</p><button type="submit" name="openCanvas" value="1">保存并进入流程画布</button>`,'task');}
function logForm(taskId='',log){const linked=state.tasks.find(t=>t.id===(log?.taskId||taskId));const attendance=log&&state.attendance.find(a=>a.logId===log.id);modal(log?'编辑投入':'记录实际投入',`<input type="hidden" name="id" value="${esc(log?.id||'')}"><div class="form-grid">${input('发生日期','date',log?.date||G.today(),'date',`required ${attendance?'readonly':''}`)}${input('实际耗时（分钟）','minutes',log?.minutes??30,'number','min="1" max="1440" step="1" required')}${catSelect(log?.category||linked?.category||'school')}${select('关联任务（可选）','taskId',[['','不关联任务'],...state.tasks.map(t=>[t.id,t.title])],log?.taskId||taskId||'')}${textarea('学习成果 / 未解决问题（可选）','evidence',log?.evidence||'')}</div>${agentHint(log?.category||linked?.category||'school')}<p class="form-note">${attendance?'此投入关联旁听，日期与分类需保持为原旁听日期及电力系统分析。':'按实际发生日期记录，跨天请分开填写。'}</p>`,'log');}
function timerLogForm(id){
 const r=state.timerBoard?.records.find(r=>r.id===id);if(!r||r.logId)throw new Error('本轮已确认投入或记录不存在');
 const task=state.tasks.find(t=>t.id===r.taskId),d=new Date(r.startedAt),localDate=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
 modal('确认本轮实际投入','<input type="hidden" name="timerId" value="'+esc(id)+'"><p class="notice">计时参考 '+window.TGTimerView.clock(r.elapsedMs)+'。请按实际投入修正；计时不代表掌握。跨天投入请在记录页分别填写，本轮在这里确认一条。</p><div class="form-grid">'+input('发生日期','date',localDate,'date','required')+input('实际投入（分钟）','minutes',Math.max(1,Math.round(r.elapsedMs/60000)),'number','min="1" max="1440" step="1" required')+catSelect(task?.category||'school')+textarea('本轮成果 / 卡点','evidence',[r.title,r.blocker,r.next?'下一步：'+r.next:''].filter(Boolean).join('；'))+'</div>','timer-log','确认并记入统计');
}
function dataDialog(){modal('数据管理',`<p>数据仅保存在本机当前入口。请定期导出 JSON 备份。</p><p class="form-note">桌面应用与浏览器入口各自保存数据；切换入口、移动文件或清除本机存储后，请使用 JSON 备份恢复。导入将整体替换，先校验并预览；建议先导出。</p><div class="actions section-gap">${btn('导出数据 JSON','export','','primary')}${btn('导入数据 JSON','import')}${btn('清空数据','clear','','danger')}</div><p class="form-note">任务 ${state.tasks.length} · 投入 ${state.logs.length} · 课程记录 ${state.courseLearningPlans.length} · 计时 ${state.timerBoard?.records.length||0}</p>`);}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a.brand');if(!b)return;if(b.dataset.focusDay){const d=document.querySelector('#fs-heat-detail');if(d)d.textContent=b.dataset.focusDay+' · 收尾 '+b.dataset.count+' 轮 · 专注 '+b.dataset.minutes+' 分钟';document.querySelectorAll('[data-focus-day]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));return;}if(b.dataset.focusRange){focusRange=b.dataset.focusRange;render();return;}if(b.dataset.page){if(!['today','week','timer','focus','dashboard','records','schedule'].includes(b.dataset.page))return;page=b.dataset.page;workbenchMenu(false);render();window.scrollTo(0,0);return;}if(b.matches('a.brand')){page='today';render();return;}const action=b.dataset.action,id=b.dataset.id;if(!action)return;e.preventDefault();safe(()=>{
switch(action){
case 'workbench-menu':workbenchMenu(!document.body.classList.contains('wb-nav-open'));break;
case 'workbench-menu-close':workbenchMenu(false);document.querySelector('#wb-menu-toggle').focus();break;
case 'close':dialog.close();break;
case 'data':dataDialog();break;
case 'task-map':dialog.close();window.TGTaskMapView.open(id);break;
case 'task-new':taskForm();break;
case 'quick-task-form':{let q={title:quick.text.trim().slice(0,150),date:G.today(),category:quick.category||'school',estimatedMinutes:quick.minutes?Number(quick.minutes):30};try{q=quickResult();}catch(err){}quickHandoff=quick.text;taskForm({title:q.title,date:q.date,category:q.category,estimatedMinutes:q.estimatedMinutes,priority:'high',status:'todo'});break;}
case 'task-edit':taskForm(state.tasks.find(t=>t.id===id));break;
case 'log':logForm(id);break;
case 'log-edit':logForm('',state.logs.find(l=>l.id===id));break;
case 'complete':change('task:complete',{id});render();toast('任务已完成。实际耗时仍按投入记录统计。');break;
case 'postpone':change('task:postpone',{id,today:G.today()});render();toast('已延期到明天，本周进度会随安排日期更新。');break;
case 'set-main':change('main:set',{date:G.today(),taskId:id});render();toast('已设为今日主任务');break;
case 'choose-main':modal('选择今日主任务',`${select('今日任务','taskId',[['','今天暂不选择'],...state.tasks.filter(t=>t.date===G.today()).map(t=>[t.id,t.title+(t.status==='done'?'（已完成）':'')])],state.mainByDate[G.today()]||'')}<p class="form-note">完成后保留主任务标记，不自动补位。可先新建任务。</p>`,'main');break;
case 'task-delete':modal('删除任务',`<p>选择是否保留这项任务的历史投入。</p><div class="dialog-actions">${btn('取消','close')}${btn('删除任务，保留投入','delete-keep',id)}${btn('任务和投入一起删除','delete-all',id,'danger')}</div>`);break;
case 'delete-keep':change('task:delete',{id,deleteLogs:false});dialog.close();render();toast('任务已删除，历史投入已保留');break;
case 'delete-all':if(confirm('确认删除任务及其全部投入？此操作无法撤销。')){change('task:delete',{id,deleteLogs:true});dialog.close();render();toast('任务及关联投入已删除');}break;
case 'log-delete':if(confirm('删除这条投入？关联旁听将同步更新。')){change('log:delete',{id});render();toast('投入已删除');}break;
case 'settings':modal('本学期方向',`${textarea('长期方向','direction',state.settings.direction)}${textarea('当前重点','focus',state.settings.focus)}${textarea('暂缓事项','defer',state.settings.defer)}<label class="check section-gap"><input name="hideStocks" type="checkbox" ${state.settings.hideStocks?'checked':''}>隐藏财务/投资目标卡（历史记录保留）</label>`,'settings');break;
case 'prev-week':if(G.teachingWeek(selected)>1)selected=G.addDays(selected,-7);render();break;
case 'next-week':if(G.teachingWeek(selected)<20)selected=G.addDays(selected,7);render();break;
case 'current-week':selected=initialWeek();render();break;
case 'all-tasks':page='week';render();document.querySelector('#all-tasks').scrollIntoView();break;
case 'task-filter':if(['all','doing','done'].includes(b.dataset.filter)){taskStatusFilter=b.dataset.filter;render();document.querySelector('#all-tasks').scrollIntoView({block:'start'});}break;
case 'go-dashboard':page='dashboard';selected=initialWeek();render();window.scrollTo(0,0);break;
case 'go-schedule':page='schedule';selected=initialWeek();workbenchMenu(false);render();window.scrollTo(0,0);break;
case 'go-week':page='week';selected=initialWeek();render();window.scrollTo(0,0);break;
case 'course':courseDetail(b.dataset.date+'|'+id);break;
case 'course-tab':activateCourseTab(b.dataset.tab);break;
case 'course-open':courseDetail(id);break;
case 'course-flow':{const c=courseSession(id);if(!c.saved)change('coursePlan:save',c.plan);const saved=G.getCoursePlan(state,c.course.id,c.date);dialog.close();window.TGTaskMapView.openCourse(saved.id);break;}
case 'course-plan-edit':courseLearningForm(id);break;
case 'course-reflect':courseLearningForm(id,true);break;
case 'course-history-open':{const p=state.courseLearningPlans.find(p=>p.id===id);if(!p)throw new Error('找不到课程记录');courseDetail(p.date+'|'+p.courseId);break;}
case 'course-copy':courseCopy('复制本节课程给ChatGPT',coursePrompt(id));break;
case 'course-copy-record':courseCopy('复制本次学习记录',G.courseLearningText(state,id));break;
case 'copy-course-text':copyCourseText();break;
case 'course-review-task':{const p=state.courseLearningPlans.find(p=>p.id===id);if(!p)throw new Error('请先保存课程记录');const t=state.tasks.find(t=>t.coursePlanId===id);taskForm(t,p);break;}
case 'attendance-plan':attendanceForm(id,false);break;
case 'attendance-attend':attendanceForm(id,true);break;
case 'attendance-cancel':{const [date,courseId]=id.split('|');if(confirm('取消这次旁听的时间预留？如已参加，参加事实和实际投入仍保留；投入可在记录页单独删除。')){change('attendance:cancel',{date,courseId,deleteLog:false});if(dialog.open)dialog.close();render();}break;}
case 'export':download(blocked&&lastRaw?lastRaw:G.exportData(state),`T计划备份-${G.today()}.json`);toast('已发起导出，请确认备份文件已保存');break;
case 'import':document.querySelector('#import-file').value='';document.querySelector('#import-file').click();break;
case 'confirm-import':if(!pendingImport)break;persist(pendingImport.state,true);pendingImport=null;dialog.close();render();toast('数据已完整导入');break;
case 'clear':if(confirm('清空本机当前入口的T计划数据？请先导出备份，其他入口的数据不受影响。')){localStorage.removeItem(KEY);lastRaw=null;state=G.newState();blocked=false;document.querySelector('#storage-error').hidden=true;dialog.close();render();toast('T计划数据已清空');}break;
}
});});
document.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const p=Object.fromEntries(new FormData(f)),type=f.dataset.form;try{
 switch(type){
 case 'quick-task':{if(quickComposing)return;quick.text=p.text||'';if(!quick.text.trim()){f.querySelector('#qa-text').focus();return;}const q=quickResult();if(!q.title)throw new Error('还缺少要做的事，只写日期或时长无法新建任务。');
  change('task:add',{title:q.title,category:q.category,date:q.date,estimatedMinutes:q.estimatedMinutes,priority:'high',status:'todo'});quick=emptyQuick();render();document.querySelector('#qa-text')?.focus();
  // Today's page lists only the main task and up to two high-priority ones; say where the rest are.
  const added=state.tasks.at(-1),shown=G.focusTasks(state,G.today());
  toast(q.date===G.today()&&(shown.main?.id===added.id||shown.secondary.some(t=>t.id===added.id))?'已添加到今天：'+q.title:'已添加：'+q.title+' · '+dayLabel(q.date)+'。可在「本周安排」的任务列表查看。');return;}
 case 'course-plan':case 'course-reflection':{const current=courseSession(p.session).plan,next={...current};if(type==='course-plan'){next.topic=p.topic;for(const key of ['preQuestions','minimumGoals','standardGoals','stretchGoals'])next[key]=p[key].split(/\r?\n/).map(x=>x.trim()).filter(Boolean);}else{next.reflection=p.reflection;next.unresolvedProblem=p.unresolvedProblem;next.evidence=new FormData(f).getAll('evidence');next.levelReached=p.levelReached;}change('coursePlan:save',next);if(e.submitter?.name==='openCanvas'){const saved=G.getCoursePlan(state,next.courseId,next.date);dialog.close();render();window.TGTaskMapView.openCourse(saved.id);return;}render();courseDetail(p.session,type==='course-reflection'?'record':'plan');toast('本节记录已保存，未自动增加投入时间');return;}
 case 'timer-log':{const next=clone(state),r=next.timerBoard?.records.find(r=>r.id===p.timerId);if(!r||r.logId)throw new Error('本轮已确认投入或记录不存在');const before=new Set(next.logs.map(l=>l.id));G.mutate(next,'log:add',{date:p.date,minutes:Number(p.minutes),category:p.category,taskId:next.tasks.some(t=>t.id===r.taskId)?r.taskId:null,evidence:p.evidence});r.logId=next.logs.find(l=>!before.has(l.id)).id;persist(next);break;}
 case 'task':{const id=p.id;delete p.id;p.coursePlanId=p.coursePlanId||null;p.estimatedMinutes=Number(p.estimatedMinutes);change(id?'task:edit':'task:add',id?{id,...p}:p);if(!id&&quickHandoff!==null&&quick.text===quickHandoff)quick=emptyQuick();if(e.submitter?.name==='openCanvas'){const tid=id||state.tasks.at(-1).id;dialog.close();render();window.TGTaskMapView.open(tid);return;}break;}
 case 'log':{const id=p.id;delete p.id;p.minutes=Number(p.minutes);p.taskId=p.taskId||null;change(id?'log:edit':'log:add',id?{id,...p}:p);break;}
 case 'main':change('main:set',{date:G.today(),taskId:p.taskId||null});break;
 case 'settings':change('settings',{direction:p.direction,focus:p.focus,defer:p.defer,hideStocks:f.elements.hideStocks.checked});break;
 case 'attendance-plan':change('attendance:plan',{date:p.date,courseId:p.courseId,plannedMinutes:Number(p.minutes)});break;
 case 'attendance-attend':{const a=state.attendance.find(a=>a.date===p.date&&a.courseId===p.courseId);const next=clone(state);if(!a)G.mutate(next,'attendance:plan',{date:p.date,courseId:p.courseId,plannedMinutes:Number(p.minutes)});G.mutate(next,'attendance:attend',{date:p.date,courseId:p.courseId,minutes:Number(p.minutes),evidence:p.evidence});persist(next);break;}
 }
 dialog.close();render();toast('已保存到本机');
 }catch(err){f.querySelector('.form-error').textContent='未保存：'+err.message;}
});
document.addEventListener('compositionstart',e=>{if(e.target.id==='qa-text')quickComposing=true;});
document.addEventListener('compositionend',e=>{if(e.target.id==='qa-text'){quickComposing=false;quick.text=e.target.value;quickPreview();}});
document.addEventListener('focusout',e=>{if(e.target.id==='qa-text')quickComposing=false;});
document.addEventListener('keydown',e=>{if(e.target.id==='qa-text'&&e.key==='Enter'&&(quickComposing||e.isComposing||e.keyCode===229))e.preventDefault();});
document.addEventListener('input',e=>{if(e.target.id!=='qa-text')return;quick.text=e.target.value;const error=e.target.form?.querySelector('.form-error');if(error)error.textContent='';quickPreview();});
document.addEventListener('change',e=>{if(e.target.id==='qa-category'||e.target.id==='qa-minutes'){quick[e.target.id==='qa-category'?'category':'minutes']=e.target.value;quickPreview();return;}if(e.target.id==='course-history-filter'){courseHistoryFilter=e.target.value;render();document.querySelector('#course-history-filter').focus();}if(e.target.name==='category'){const hint=document.querySelector('#agent-evidence-hint');if(hint)hint.hidden=e.target.value!=='agent';}if(e.target.id==='week-number'){const w=Number(e.target.value);if(Number.isInteger(w)&&w>=1&&w<=20){selected=G.addDays('2026-09-07',(w-1)*7);render();}}});
document.querySelector('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('备份文件超过5MB，请检查文件');pendingImport=G.parseImport(await file.text());modal('导入预览',`<p>已通过格式与数据校验。</p><p class="form-note">导出时间：${esc(pendingImport.exportedAt)}</p><p>任务 ${pendingImport.state.tasks.length} 条 · 投入 ${pendingImport.state.logs.length} 条 · 课程学习 ${pendingImport.state.courseLearningPlans.length} 次 · 计时 ${pendingImport.state.timerBoard?.records.length||0} 轮</p><p class="notice">确认后整体替换当前数据。建议先导出当前备份。</p><div class="dialog-actions">${btn('取消','close')}${btn('确认替换并导入','confirm-import','','primary')}</div>`);}catch(err){pendingImport=null;toast('导入失败，原数据保持不变：'+err.message);}});
document.addEventListener('keydown',e=>{if(!e.target.matches('[data-action="course-tab"]'))return;const tabs=['plan','record','tasks'],current=tabs.indexOf(e.target.dataset.tab);let next;if(e.key==='ArrowRight')next=(current+1)%tabs.length;else if(e.key==='ArrowLeft')next=(current+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();activateCourseTab(tabs[next],true);});
dialog.addEventListener('close',()=>{quickHandoff=null;});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
render();
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('wb-nav-open')){workbenchMenu(false);document.querySelector('#wb-menu-toggle').focus();}});
window.TGTaskMapView.init({state:()=>state,persist,toast,refresh:render,prepare:(id,c)=>window.TGTimerView.prepare(id,c),edit:id=>taskForm(state.tasks.find(t=>t.id===id))});
window.TGTimerView.init({state:()=>state,persist,refresh:()=>{if(page==='timer')render();},open:()=>{page='timer';render();window.scrollTo(0,0);},toast,log:timerLogForm});
// Refresh date at midnight or on return, without discarding an open form.
let visibleDate=G.today(), visibleCalendar=K.events.map(e=>K.eventStatus(e.id)).join(',');
function refreshClock(){const nextDate=G.today(),nextCalendar=K.events.map(e=>K.eventStatus(e.id)).join(',');if(!dialog.open&&(nextDate!==visibleDate||nextCalendar!==visibleCalendar)){if(nextDate!==visibleDate){visibleDate=nextDate;selected=initialWeek();}visibleCalendar=nextCalendar;render();}}
setInterval(refreshClock,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshClock();});
})();

